fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    debug_assert!(len > 0, "list must be non-empty");

    let k = n % len;      // effective rotation
    let s = len - k;      // split point per problem statement

    let mut out = Vec::with_capacity(len);
    out.extend_from_slice(&list[s..]);  // suffix [s, len)
    out.extend_from_slice(&list[..s]);  // prefix [0, s)
    out
}

